-- Generated from dataframe.dtypes. PostgreSQL 14+. Run once in a new schema.
BEGIN;
CREATE SCHEMA geochem;


CREATE TABLE geochem.import_batch (
    import_batch_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    source_name text NOT NULL,
    source_sha256 text,
    imported_at timestamptz NOT NULL DEFAULT current_timestamp,
    comment text,
    CHECK (source_sha256 IS NULL OR source_sha256 ~ '^[0-9a-fA-F]{64}$')
);


CREATE TABLE geochem.well (
    well_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    "well_name" text,
    "alt_names" bigint,
    "site_type" text,
    "purpose" text,
    "result" text,
    "status" text,
    "well_comment" text,
    "total_md" double precision,
    "tmd_datum" text,
    "total_tvd" double precision,
    "lat" double precision,
    "long" double precision,
    "x_coord" double precision,
    "y_coord" double precision,
    "srs_code" bigint,
    "region" text,
    "area" text,
    "country" text,
    "basin" text,
    "quad" bigint,
    "block" bigint,
    "prospect" text,
    "asset" text,
    "field" text,
    "loc_char" text,
    "abs_datum" text,
    "water_dpth" double precision,
    "dr_height" double precision,
    "td_chron" text,
    "td_lstrat" text,
    "licence" text,
    "company" text,
    "operator" text,
    "start_date" text,
    "drill_days" bigint,
    "compl_date" text,
    "rig_name" text,
    "bht" bigint
);

COMMENT ON COLUMN geochem.well."well_name" IS 'Well / Well Name / string';

COMMENT ON COLUMN geochem.well."alt_names" IS 'Well / Alt Names / Int64';

COMMENT ON COLUMN geochem.well."site_type" IS 'Well / Site type / string';

COMMENT ON COLUMN geochem.well."purpose" IS 'Well / Purpose / string';

COMMENT ON COLUMN geochem.well."result" IS 'Well / Result / string';

COMMENT ON COLUMN geochem.well."status" IS 'Well / Status / string';

COMMENT ON COLUMN geochem.well."well_comment" IS 'Well / Well comment / string';

COMMENT ON COLUMN geochem.well."total_md" IS 'Well / Total MD [m] / Float64';

COMMENT ON COLUMN geochem.well."tmd_datum" IS 'Well / TMD datum / string';

COMMENT ON COLUMN geochem.well."total_tvd" IS 'Well / Total TVD [m] / Float64';

COMMENT ON COLUMN geochem.well."lat" IS 'Well / Lat [°] / Float64';

COMMENT ON COLUMN geochem.well."long" IS 'Well / Long [°] / Float64';

COMMENT ON COLUMN geochem.well."x_coord" IS 'Well / X coord [m] / Float64';

COMMENT ON COLUMN geochem.well."y_coord" IS 'Well / Y coord [m] / Float64';

COMMENT ON COLUMN geochem.well."srs_code" IS 'Well / SRS code / Int64';

COMMENT ON COLUMN geochem.well."region" IS 'Well / Region / string';

COMMENT ON COLUMN geochem.well."area" IS 'Well / Area / string';

COMMENT ON COLUMN geochem.well."country" IS 'Well / Country / string';

COMMENT ON COLUMN geochem.well."basin" IS 'Well / Basin / string';

COMMENT ON COLUMN geochem.well."quad" IS 'Well / Quad / Int64';

COMMENT ON COLUMN geochem.well."block" IS 'Well / Block / Int64';

COMMENT ON COLUMN geochem.well."prospect" IS 'Well / Prospect / string';

COMMENT ON COLUMN geochem.well."asset" IS 'Well / Asset / string';

COMMENT ON COLUMN geochem.well."field" IS 'Well / Field / string';

COMMENT ON COLUMN geochem.well."loc_char" IS 'Well / Loc char / string';

COMMENT ON COLUMN geochem.well."abs_datum" IS 'Well / Abs datum / string';

COMMENT ON COLUMN geochem.well."water_dpth" IS 'Well / Water dpth [m] / Float64';

COMMENT ON COLUMN geochem.well."dr_height" IS 'Well / DR height [m] / Float64';

COMMENT ON COLUMN geochem.well."td_chron" IS 'Well / TD Chron / string';

COMMENT ON COLUMN geochem.well."td_lstrat" IS 'Well / TD Lstrat / string';

COMMENT ON COLUMN geochem.well."licence" IS 'Well / Licence / string';

COMMENT ON COLUMN geochem.well."company" IS 'Well / Company / string';

COMMENT ON COLUMN geochem.well."operator" IS 'Well / Operator / string';

COMMENT ON COLUMN geochem.well."start_date" IS 'Well / Start date / string';

COMMENT ON COLUMN geochem.well."drill_days" IS 'Well / Drill days [Euc] / Int64';

COMMENT ON COLUMN geochem.well."compl_date" IS 'Well / Compl date / string';

COMMENT ON COLUMN geochem.well."rig_name" IS 'Well / Rig Name / string';

COMMENT ON COLUMN geochem.well."bht" IS 'Well / BHT [°C] / Int64';

CREATE TABLE geochem.sample (
    sample_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    well_id bigint REFERENCES geochem.well(well_id),
    "name" text,
    "company" text,
    "internal" text,
    "vendor_source" text,
    "top_md" double precision,
    "base_md" double precision,
    "md_datum" text,
    "tvd_datum" text,
    "type" text,
    "category" text,
    "rock_type" text,
    "liquid_type" text,
    "gas_type" text,
    "container_type" text,
    "test" text,
    "container" text,
    "mud_type" text,
    "repeat" text,
    "sample_comment" text,
    "site_type" text,
    "prj_name" text,
    "sam_date" text,
    "preparation" text
);

COMMENT ON COLUMN geochem.sample."name" IS 'Sample / Name / string';

COMMENT ON COLUMN geochem.sample."company" IS 'Sample / Company / string';

COMMENT ON COLUMN geochem.sample."internal" IS 'Sample / Internal# / string';

COMMENT ON COLUMN geochem.sample."vendor_source" IS 'Sample / Vendor Source / string';

COMMENT ON COLUMN geochem.sample."top_md" IS 'Sample / Top MD [m] / Float64';

COMMENT ON COLUMN geochem.sample."base_md" IS 'Sample / Base MD [m] / Float64';

COMMENT ON COLUMN geochem.sample."md_datum" IS 'Sample / MD datum / string';

COMMENT ON COLUMN geochem.sample."tvd_datum" IS 'Sample / TVD datum / string';

COMMENT ON COLUMN geochem.sample."type" IS 'Sample / Type / string';

COMMENT ON COLUMN geochem.sample."category" IS 'Sample / Category / string';

COMMENT ON COLUMN geochem.sample."rock_type" IS 'Sample / Rock type / string';

COMMENT ON COLUMN geochem.sample."liquid_type" IS 'Sample / Liquid type / string';

COMMENT ON COLUMN geochem.sample."gas_type" IS 'Sample / Gas type / string';

COMMENT ON COLUMN geochem.sample."container_type" IS 'Sample / Container type / string';

COMMENT ON COLUMN geochem.sample."test" IS 'Sample / Test# / string';

COMMENT ON COLUMN geochem.sample."container" IS 'Sample / Container# / string';

COMMENT ON COLUMN geochem.sample."mud_type" IS 'Sample / Mud type / string';

COMMENT ON COLUMN geochem.sample."repeat" IS 'Sample / Repeat / string';

COMMENT ON COLUMN geochem.sample."sample_comment" IS 'Sample / Sample comment / string';

COMMENT ON COLUMN geochem.sample."site_type" IS 'Sample / Site type / string';

COMMENT ON COLUMN geochem.sample."prj_name" IS 'Sample / Prj name / string';

COMMENT ON COLUMN geochem.sample."sam_date" IS 'Sample / Sam date / string';

COMMENT ON COLUMN geochem.sample."preparation" IS 'Sample / Preparation / string';

CREATE TABLE geochem.sample_geology (
    sample_geology_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    sample_id bigint NOT NULL REFERENCES geochem.sample(sample_id),
    "alt_top_lstrat" text,
    "alt_base_lstrat" text,
    "alt_lstrat_source" text,
    "alt_top_lstrat_gp" text,
    "alt_base_lstrat_gp" text,
    "alt_top_lstrat_fm" text,
    "alt_base_lstrat_fm" text,
    "alt_top_lstrat_mb" text,
    "alt_base_lstrat_mb" text,
    "alt_top_cstrat" text,
    "alt_base_cstrat" text,
    "alt_cstrat_source" text,
    "alt_top_cstrat_epo" text,
    "alt_base_cstrat_epo" text,
    "alt_top_cstrat_per" text,
    "alt_base_cstrat_per" text,
    "alt_top_cstrat_age" text,
    "alt_base_cstrat_age" text
);

COMMENT ON COLUMN geochem.sample_geology."alt_top_lstrat" IS 'Geol / Alt Top Lstrat / string';

COMMENT ON COLUMN geochem.sample_geology."alt_base_lstrat" IS 'Geol / Alt Base Lstrat / string';

COMMENT ON COLUMN geochem.sample_geology."alt_lstrat_source" IS 'Geol / Alt Lstrat Source / string';

COMMENT ON COLUMN geochem.sample_geology."alt_top_lstrat_gp" IS 'Geol / Alt Top Lstrat(Gp) / string';

COMMENT ON COLUMN geochem.sample_geology."alt_base_lstrat_gp" IS 'Geol / Alt Base Lstrat(Gp) / string';

COMMENT ON COLUMN geochem.sample_geology."alt_top_lstrat_fm" IS 'Geol / Alt Top Lstrat(Fm) / string';

COMMENT ON COLUMN geochem.sample_geology."alt_base_lstrat_fm" IS 'Geol / Alt Base Lstrat(Fm) / string';

COMMENT ON COLUMN geochem.sample_geology."alt_top_lstrat_mb" IS 'Geol / Alt Top Lstrat(Mb) / string';

COMMENT ON COLUMN geochem.sample_geology."alt_base_lstrat_mb" IS 'Geol / Alt Base Lstrat(Mb) / string';

COMMENT ON COLUMN geochem.sample_geology."alt_top_cstrat" IS 'Geol / Alt Top Cstrat / string';

COMMENT ON COLUMN geochem.sample_geology."alt_base_cstrat" IS 'Geol / Alt Base Cstrat / string';

COMMENT ON COLUMN geochem.sample_geology."alt_cstrat_source" IS 'Geol / Alt Cstrat Source / string';

COMMENT ON COLUMN geochem.sample_geology."alt_top_cstrat_epo" IS 'Geol / Alt Top Cstrat(Epo) / string';

COMMENT ON COLUMN geochem.sample_geology."alt_base_cstrat_epo" IS 'Geol / Alt Base Cstrat(Epo) / string';

COMMENT ON COLUMN geochem.sample_geology."alt_top_cstrat_per" IS 'Geol / Alt Top Cstrat(Per) / string';

COMMENT ON COLUMN geochem.sample_geology."alt_base_cstrat_per" IS 'Geol / Alt Base Cstrat(Per) / string';

COMMENT ON COLUMN geochem.sample_geology."alt_top_cstrat_age" IS 'Geol / Alt Top Cstrat(Age) / string';

COMMENT ON COLUMN geochem.sample_geology."alt_base_cstrat_age" IS 'Geol / Alt Base Cstrat(Age) / string';

CREATE TABLE geochem.reference_document (
    reference_document_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    "author" text,
    "year" bigint,
    "doc" text,
    "source" text
);

COMMENT ON COLUMN geochem.reference_document."author" IS 'Ref / Author / string';

COMMENT ON COLUMN geochem.reference_document."year" IS 'Ref / Year / Int64';

COMMENT ON COLUMN geochem.reference_document."doc" IS 'Ref / Doc# / string';

COMMENT ON COLUMN geochem.reference_document."source" IS 'Ref / Source / string';


-- A source row is provenance, not a claim that sample names are unique.
CREATE TABLE geochem.source_record (
    source_record_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    import_batch_id bigint NOT NULL REFERENCES geochem.import_batch(import_batch_id),
    row_number bigint NOT NULL CHECK (row_number >= 0),
    sample_id bigint NOT NULL REFERENCES geochem.sample(sample_id),
    sample_geology_id bigint,
    -- Optional lossless source cells as [[group, label, value], ...].
    -- Useful for rejected values and reconstruction; not the query store.
    raw_cells jsonb CHECK (raw_cells IS NULL OR jsonb_typeof(raw_cells) = 'array'),
    UNIQUE (import_batch_id, row_number),
    UNIQUE (source_record_id, sample_id)
);
ALTER TABLE geochem.sample_geology
    ADD CONSTRAINT sample_geology_identity UNIQUE (sample_geology_id, sample_id);
ALTER TABLE geochem.source_record
    ADD CONSTRAINT source_geology_sample_fk FOREIGN KEY (sample_geology_id, sample_id)
    REFERENCES geochem.sample_geology(sample_geology_id, sample_id);

CREATE TABLE geochem.source_record_reference (
    source_record_id bigint NOT NULL REFERENCES geochem.source_record(source_record_id),
    reference_document_id bigint NOT NULL REFERENCES geochem.reference_document(reference_document_id),
    PRIMARY KEY (source_record_id, reference_document_id)
);

CREATE TABLE geochem.data_group (
    group_name text PRIMARY KEY,
    scope text NOT NULL CHECK (scope IN ('core', 'analysis')),
    UNIQUE (group_name, scope)
);

-- Exact (group_name, source_label) identifies an imported DataFrame column.
CREATE TABLE geochem.source_field (
    source_field_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    group_name text NOT NULL REFERENCES geochem.data_group(group_name),
    source_label text NOT NULL,
    source_dtype text NOT NULL CHECK (source_dtype IN ('string', 'Int64', 'Float64')),
    unit_label text,
    target_table text NOT NULL,
    target_column text,
    UNIQUE (group_name, source_label),
    UNIQUE (source_field_id, group_name, source_dtype),
    CHECK ((target_table = 'analysis_result' AND target_column IS NULL)
        OR (target_table IN ('well', 'sample', 'sample_geology', 'reference_document')
            AND target_column IS NOT NULL))
);

CREATE TABLE geochem.analysis_run (
    analysis_run_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    sample_id bigint NOT NULL REFERENCES geochem.sample(sample_id),
    source_record_id bigint NOT NULL,
    group_name text NOT NULL,
    scope text NOT NULL DEFAULT 'analysis' CHECK (scope = 'analysis'),
    repeat_number integer NOT NULL DEFAULT 1 CHECK (repeat_number > 0),
    -- Optional parsed date; the source 'Date' string remains an analysis_result.
    analyzed_on date,
    FOREIGN KEY (source_record_id, sample_id)
        REFERENCES geochem.source_record(source_record_id, sample_id),
    FOREIGN KEY (group_name, scope) REFERENCES geochem.data_group(group_name, scope),
    UNIQUE (source_record_id, group_name, repeat_number),
    UNIQUE (analysis_run_id, group_name)
);

-- Typed EAV: one value per source field per analysis run.
-- Composite foreign keys prevent mixing groups and mismatching declared dtypes.
CREATE TABLE geochem.analysis_result (
    analysis_run_id bigint NOT NULL,
    source_field_id bigint NOT NULL,
    group_name text NOT NULL,
    source_dtype text NOT NULL,
    value_float double precision,
    value_int bigint,
    value_text text,
    PRIMARY KEY (analysis_run_id, source_field_id),
    FOREIGN KEY (analysis_run_id, group_name)
        REFERENCES geochem.analysis_run(analysis_run_id, group_name),
    FOREIGN KEY (source_field_id, group_name, source_dtype)
        REFERENCES geochem.source_field(source_field_id, group_name, source_dtype),
    CHECK (
        (source_dtype = 'Float64' AND value_float IS NOT NULL AND value_int IS NULL AND value_text IS NULL)
        OR (source_dtype = 'Int64' AND value_int IS NOT NULL AND value_float IS NULL AND value_text IS NULL)
        OR (source_dtype = 'string' AND value_text IS NOT NULL AND value_float IS NULL AND value_int IS NULL)
    ),
    CHECK (value_float IS NULL OR value_float NOT IN
        ('NaN'::double precision, 'Infinity'::double precision, '-Infinity'::double precision))
);

CREATE INDEX sample_well_idx ON geochem.sample(well_id);
CREATE INDEX well_name_idx ON geochem.well(well_name);
CREATE INDEX sample_name_idx ON geochem.sample(name);
CREATE INDEX sample_depth_idx ON geochem.sample(top_md, base_md);
CREATE INDEX geology_sample_idx ON geochem.sample_geology(sample_id);
CREATE INDEX source_sample_idx ON geochem.source_record(sample_id);
CREATE INDEX source_geology_idx ON geochem.source_record(sample_geology_id, sample_id);
CREATE INDEX reference_document_idx ON geochem.source_record_reference(reference_document_id);
CREATE INDEX analysis_sample_group_idx ON geochem.analysis_run(sample_id, group_name);
CREATE INDEX result_field_float_idx ON geochem.analysis_result(source_field_id, value_float)
    WHERE value_float IS NOT NULL;
CREATE INDEX result_field_int_idx ON geochem.analysis_result(source_field_id, value_int)
    WHERE value_int IS NOT NULL;

CREATE VIEW geochem.v_analysis_result AS
SELECT a.sample_id, a.source_record_id, a.analysis_run_id, a.repeat_number,
       a.analyzed_on, a.group_name, f.source_label, f.unit_label, r.source_dtype,
       r.value_float, r.value_int, r.value_text
FROM geochem.analysis_run a
JOIN geochem.analysis_result r USING (analysis_run_id, group_name)
JOIN geochem.source_field f USING (source_field_id, group_name, source_dtype);


